=Subject:
{{ $('Loop Over Items').item.json.Subject }}

Email body:
{{ $('Loop Over Items').item.json.snippet }}

conditions.leftValue:
={{ (() => {
  const email = $('Loop Over Items').item.json;

  const subject = String(email.Subject || email.subject || '')
    .trim().toLowerCase();

  const sender = String(email.From || email.from || '')
    .toLowerCase();

  const recommendation =
    /^(our recommendation:|your recommended jobs|jobs you may like)/.test(subject);

  const jobDigest =
    /^\d+\s+new\s+.*\bjobs?\b/.test(subject);

  const prospectsAlert =
    sender.includes('jobs@mail.prospects.ac.uk') &&
    /^new jobs:/.test(subject);

  const jobAlert =
    /^(job alert|your job alert)/.test(subject) &&
    /(indeed|totaljobs|targetjobs|reed|linkedin)/.test(sender);

  return (
    recommendation || jobDigest || prospectsAlert || jobAlert
  ) ? 'SKIP' : 'PROCESS';
})() }}
